const D=window.APP_DATA,labels=D.method.status,dims=['Alle','Kontext','Ökologisch','Ökonomisch','Sozial','Management'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let matrixFilter='Alle',catalogFilter='Alle';
const pill=s=>`<span class="pill ${s}">${labels[s]}</span>`;
const ref=s=>esc(s).replace(/\b([KLATCE]),/g,(_,id)=>`<a class="textlink" href="https://doi.org/${D.sources.find(s=>s.id===id).doi}" target="_blank" rel="noopener">${id}</a>,`);
function filters(id,active,kind){document.getElementById(id).innerHTML=dims.map(d=>`<button class="filter ${active===d?'active':''}" data-kind="${kind}" data-filter="${d}" aria-pressed="${active===d}">${d}</button>`).join('')}
function cards(){document.getElementById('cases').innerHTML=D.cases.map(c=>{const s=AppLogic.stats(D,c.id);return`<article class="case" style="--case-color:${c.color}"><span class="tag">${c.kind}</span><h3>${c.name}</h3><p class="subtitle">${c.subtitle}</p><p class="description">${c.summary}</p><div class="coverage"><div><span>Quellenhinweise zu Wirkungsfragen</span><b>${s.covered}/${s.total}</b></div><div class="stack" role="img" aria-label="${s.num} Zahlenangaben, ${s.qual} qualitative Hinweise, ${s.plan} Planangaben, ${s.gap} offene Fragen">${['num','qual','plan','gap'].map(k=>`<i class="${k}" style="width:${100*s[k]/s.total}%"></i>`).join('')}</div><small>${s.num} Zahl${s.num===1?'':'en'} berichtet · kein Gesamtindex</small></div><button class="textlink" data-case="${c.id}">Vollständige Anwendung</button></article>`}).join('')}
function matrix(){filters('matrix-filters',matrixFilter,'matrix');document.getElementById('matrix-head').innerHTML=`<tr><th scope="col">Frage / Thema</th>${D.cases.map(c=>`<th scope="col">${c.name}<small>${c.kind}</small></th>`).join('')}</tr>`;document.getElementById('matrix-body').innerHTML=D.questions.filter(q=>matrixFilter==='Alle'||q.dimension===matrixFilter).map(q=>`<tr><th scope="row"><span class="qid">${q.id}</span>${q.topic}<small>${q.dimension}</small></th>${D.cases.map(c=>{const a=D.answers[c.id][q.id],note=a.number?`${a.number.actual} ${a.number.unit}`:a.grade!==null?`Reifegrad ${a.grade}/3`:'';return`<td><button class="cell" data-answer="${c.id}:${q.id}" aria-label="${c.name}: ${q.id} ${q.topic} – ${labels[a.status]}">${pill(a.status)}${note?`<small>${esc(note)}</small>`:''}</button></td>`}).join('')}</tr>`).join('')}
function catalog(){filters('catalog-filters',catalogFilter,'catalog');const normalize=s=>s.toLocaleLowerCase('de').replace(/₂/g,'2');const term=normalize(document.getElementById('search').value);const list=D.questions.filter(q=>(catalogFilter==='Alle'||q.dimension===catalogFilter)&&normalize([q.id,q.topic,q.text,q.format,q.source].join(' ')).includes(term));document.getElementById('count').textContent=`${list.length} von ${D.questions.length} Fragen`;document.getElementById('questions').innerHTML=list.length?list.map(q=>`<details class="question"><summary><span class="qid">${q.id}</span><span><small>${q.dimension} / ${q.topic}</small><b>${esc(q.text)}</b></span></summary><div class="q-details"><div><b>Antwortformat</b><p>${esc(q.format)}</p></div><div><b>Bewertungsregel</b><p>${esc(q.rule)}</p></div><p class="source-line">Ableitung: ${ref(q.source)} · eigene Formulierung<br><button class="textlink" data-question="${q.id}">Vier Anwendungen ansehen</button></p></div></details>`).join(''):'<p class="empty">Keine passende Frage. Ändere Suchbegriff oder Kategorie.</p>';document.getElementById('expand').textContent='Alle Details öffnen'}
function block(c,q){let a=D.answers[c.id][q.id];return`<section class="answer-block">${pill(a.status)}${a.grade!==null?`<span class="grade">Reifegrad ${a.grade}/3 · eigene Einordnung</span>`:''}<p>${esc(a.text)}</p>${a.missing?`<p class="missing"><b>Noch erforderlich:</b> ${esc(a.missing)}</p>`:''}<p class="source-line">Beleg: ${ref(a.ref)} · PDF-Zählung</p></section>`}
const dialog=document.getElementById('detail');function show(html){document.getElementById('detail-content').innerHTML=html;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;dialog.querySelector('.close').focus()}
function answer(cid,qid){const c=D.cases.find(c=>c.id===cid),q=D.questions.find(q=>q.id===qid);show(`<p class="eyebrow">${c.name} / ${q.dimension} / ${q.id}</p><h2>${esc(q.text)}</h2>${block(c,q)}<p class="muted">Erwartetes Format: ${esc(q.format)}</p><button class="textlink" data-question="${qid}">Diese Frage für alle Fälle vergleichen</button>`)}
function question(id){const q=D.questions.find(q=>q.id===id);show(`<p class="eyebrow">${q.dimension} / ${id}</p><h2>${esc(q.text)}</h2>${D.cases.map(c=>`<h3>${c.name}</h3>${block(c,q)}`).join('')}`)}
function caseDetail(id){const c=D.cases.find(c=>c.id===id),s=AppLogic.stats(D,id);show(`<p class="eyebrow">VOLLSTÄNDIGE FALLANWENDUNG / ${c.kind}</p><h2>${c.name}: ${c.subtitle}</h2><p>${c.summary}</p><p><b>Ergebnis:</b> ${c.takeaway}<br><b>Nächster Nachweis:</b> ${c.next}</p><p class="muted">${s.covered}/${s.total} Wirkungsfragen haben Quellenhinweise, ${s.num} davon einen Zahlenwert. Dies ist keine Nachhaltigkeitsbewertung.</p>${dims.slice(1).map(dim=>`<h3>${dim}</h3>${D.questions.filter(q=>q.dimension===dim).map(q=>`<details class="question"><summary><span class="qid">${q.id}</span><span><b>${esc(q.text)}</b></span></summary><div class="detail-body">${block(c,q)}</div></details>`).join('')}`).join('')}`)}
function page(name,scroll=true){if(!['vergleich','katalog','methode'].includes(name))name='vergleich';document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==name);document.querySelectorAll('.nav').forEach(b=>{const on=b.dataset.page===name;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(scroll)window.scrollTo({top:0,behavior:'instant'})}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.page){history.pushState(null,'',`#${b.dataset.page}`);page(b.dataset.page);if(dialog.open)dialog.close()}if(b.dataset.kind){if(b.dataset.kind==='matrix'){matrixFilter=b.dataset.filter;matrix()}else{catalogFilter=b.dataset.filter;catalog()}}if(b.dataset.answer){const [c,q]=b.dataset.answer.split(':');answer(c,q)}if(b.dataset.question)question(b.dataset.question);if(b.dataset.case)caseDetail(b.dataset.case)});
document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.getElementById('search').addEventListener('input',catalog);document.getElementById('expand').addEventListener('click',e=>{const all=[...document.querySelectorAll('#questions details')],open=all.some(x=>!x.open);all.forEach(x=>x.open=open);e.target.textContent=open?'Alle Details schließen':'Alle Details öffnen'});
function calc(){const r=AppLogic.score(...['actual','baseline','target','direction'].map(id=>document.getElementById(id).value));document.getElementById('result').innerHTML=r.error?`<span class="error">${r.error}</span>`:`<strong>${r.value.toLocaleString('de-DE',{maximumFractionDigits:1})}</strong><small>von 100 Punkten</small>`}
['actual','baseline','target','direction'].forEach(id=>document.getElementById(id).addEventListener('input',calc));
document.getElementById('revision').textContent=D.method.revision;
document.getElementById('aggregation').textContent=D.method.aggregation;document.getElementById('missing').textContent=D.method.missing;document.getElementById('grades').textContent=D.method.grade;
document.getElementById('sources').innerHTML=D.sources.map(s=>`<article class="source"><span>${s.id}</span><div><h3>${s.title}</h3><p>${s.author}</p><p>${s.use}</p><a class="textlink" href="https://doi.org/${s.doi}" target="_blank" rel="noopener">Buch beim Verlag</a></div></article>`).join('');
window.addEventListener('hashchange',()=>page(location.hash.slice(1)));window.addEventListener('popstate',()=>page(location.hash.slice(1)));cards();matrix();catalog();calc();page(location.hash.slice(1),false);
